// One prompt for the whole batch. Strict rules keep the model from inventing numbers.
const mails = $input.all().map(i => ({
  id: i.json.id,
  from: i.json.From || '',
  subject: i.json.Subject || '',
  text: String(i.json.text || i.json.snippet || '').slice(0, 4000),
  mailDate: i.json.date || '',
}));
const sys = "You extract paid business invoices and payment receipts from emails. "
  + "STRICT RULES, this feeds bookkeeping: "
  + "1) Only take an amount that appears LITERALLY in the text. NEVER guess. "
  + "2) If there is no clear amount with a currency, skip the mail entirely. "
  + "3) Always take the TOTAL (gross). Never the VAT share, never a single line item. "
  + "4) Skip: order confirmations without an amount, newsletters, ads, password mails, "
  + "payment reminders without a sum. "
  + "5) date as full YYYY-MM-DD. Prefer the invoice date in the text, else mailDate. "
  + "Return ONLY a JSON array, one object per confirmed invoice: "
  + '[{\"id\":\"<mail id>\",\"vendor\":\"\",\"amount\":<number>,'
  + '\"currency\":\"EUR|USD\",\"date\":\"YYYY-MM-DD\",\"description\":\"\"}]. "
  + "No invoices found: return []";
const body = JSON.stringify({
  model: 'claude-haiku-4-5',
  max_tokens: 2000,
  system: sys,
  messages: [{ role: 'user', content: JSON.stringify(mails).slice(0, 20000) }],
});
return [{ json: { anthropicBody: body } }];

// Second safety net: whatever the model returns still has to survive these checks.
let raw = '';
try { raw = $json.content[0].text; } catch (e) {}
let arr = [];
try { arr = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) {}
if (!Array.isArray(arr)) arr = [];
const out = [];
for (const o of arr) {
  const amount = Number(String(o.amount).replace(',', '.'));
  const date = String(o.date || '');
  if (!o.id || !amount || amount <= 0) continue;        // no amount -> drop
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;      // no clean date -> drop
  out.push({ json: {
    msgId: o.id,
    vendor: String(o.vendor || '').slice(0, 80),
    amount: amount,
    currency: (o.currency === 'USD' ? 'USD' : 'EUR'),
    date: date,
    description: String(o.description || '').slice(0, 200),
  } });
}
return out;
